# The lanes every install had while they were code (states.DEFAULT_STATES, copied:
# a migration must not import the module it may later disagree with).
DEFAULTS = [
    ("triage", "Triage", "triage", True),
    ("backlog", "Backlog", "backlog", True),
    ("todo", "Todo", "unstarted", True),
    ("in_progress", "In Progress", "started", True),
    ("done", "Done", "completed", True),
    ("canceled", "Canceled", "canceled", False),
    ("duplicate", "Duplicate", "duplicate", False),
]


def seed(apps, schema_editor):
    """The default lanes, with the keys tickets already hold; and a lane for any other
    key a ticket holds, so no ticket is left in a lane that does not exist."""
    TicketState = apps.get_model("dev_tickets", "TicketState")
    DevTicket = apps.get_model("dev_tickets", "DevTicket")
    position = 0
    for position, (key, name, type_, on_board) in enumerate(DEFAULTS):
        TicketState.objects.get_or_create(
            key=key, defaults={"name": name, "type": type_, "on_board": on_board, "position": position}
        )
    known = set(TicketState.objects.values_list("key", flat=True))
    for key in sorted(set(DevTicket.objects.values_list("state", flat=True)) - known):
        position += 1
        TicketState.objects.create(
            key=key, name=key.replace("_", " ").title()[:40], type="unstarted", position=position
        )


